{
  "id": "V045",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "한국어 기업 기사를 영어 독자가 이해할 수 있도록 번역하려는 목적이 보존되었습니다."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "번역문을 원문과 비교해 고유명사·수치 누락 여부를 확인하고 편집자가 검토하는 흐름이 보존되었습니다."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "기업 소식 기사와 그 영어 번역문이 다뤄집니다."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "한국어 기사 원문이 입력으로 보존되었습니다."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "영어 번역문이 결과물로 명시되었습니다."
    },
    {
      "field": "constraints",
      "score": 1,
      "reason": "고유명사와 수치의 보존은 다뤄지지만, 원문에 없는 인용이나 성과를 추가하지 않는 제약은 모든 뷰에서 빠졌습니다."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "새로운 기능을 추가한다고 볼 근거가 없습니다."
    },
    {
      "field": "roles",
      "score": 1,
      "reason": "편집자의 원문 비교 검토는 보존되지만 게시 결정이 편집자에게 있다는 점은 모든 뷰에서 빠졌습니다."
    }
  ],
  "issues": [
    {
      "type": "OMISSION",
      "source_quote": "원문에 없는 인용이나 성과를 추가하지 않으며",
      "view_quote": "",
      "reason": "번역문에 원문에 없는 인용이나 성과를 넣지 않는 제약이 세 뷰 모두에 없습니다."
    },
    {
      "type": "OMISSION",
      "source_quote": "게시 결정은 편집자가 합니다.",
      "view_quote": "",
      "reason": "게시 결정의 주체가 편집자라는 점이 세 뷰 모두에 없습니다."
    }
  ],
  "permission_interpretation": "편집자가 게시를 결정한다는 원문의 권한 배분은 보존되지 않았습니다. 뷰에는 AI나 다른 주체가 게시하거나 승인한다는 주장은 없습니다."
}
